 "content": "from collections import deque

def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    barrier_row = next((r for r in range(h) if a[r][0] != 0 and all(x == a[r][0] for x in a[r])), None)
    barrier_col = next((c for c in range(w) if a[0][c] != 0 and all(a[r][c] == a[0][c] for r in range(h))), None)
    if barrier_row is not None:
        dr = -1 if barrier_row < h // 2 else 1
        cells = {(r, c) for r in range(h) for c in range(w) if a[r][c] != 0 and r != barrier_row}
    elif barrier_col is not None:
        dc = -1 if barrier_col < w // 2 else 1
        cells = {(r, c) for r in range(h) for c in range(w) if a[r][c] != 0 and c != barrier_col}
    else:
        return a
    comps = []
    while cells:
        start = cells.pop()
        color = a[start[0]][start[1]]
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in cells and a[nr][nc] == color:
                    cells.remove((nr,nc)); comp.add((nr,nc)); q.append((nr,nc))
        comps.append((color, comp))
    if barrier_row is not None:
        comps.sort(key=lambda item: min(r for r,c in item[1]), reverse=(dr > 0))
        for color, comp in comps:
            while True:
                shifted = {(r+dr,c) for r,c in comp}
                if any(not (0 <= r < h and 0 <= c < w) or (a[r][c] != 0 and (r,c) not in comp) for r,c in shifted):
                    break
                for r,c in comp: a[r][c] = 0
                comp = shifted
                for r,c in comp: a[r][c] = color
    else:
        comps.sort(key=lambda item: min(c for r,c in item[1]), reverse=(dc > 0))
        for color, comp in comps:
            while True:
                shifted = {(r,c+dc) for r,c in comp}
                if any(not (0 <= r < h and 0 <= c < w) or (a[r][c] != 0 and (r,c) not in comp) for r,c in shifted):
                    break
                for r,c in comp: a[r][c] = 0
                comp = shifted
                for r,c in comp: a[r][c] = color
    return a
